from pathlib import Path
import base64, gzip, shutil, sys

PROJECT_HOME = Path(r"C:\Users\Kane\Documents\Projects\Cylinder_Quote_To_HTML")
APP_DIR = PROJECT_HOME / "Cylinder_Quote_Web_Milestone_1"
FILES = {
    'app/templates/index.html': '',
    'app/static/styles.css': '',
    'app/static/app.js': '',
    'app/catalog.py': '',
}

def main():
    print("=" * 72)
    print("JIT CYLINDER QUOTE - ORDERENTRY REPLICA V1 PATCH")
    print("=" * 72)
    if not APP_DIR.exists():
        print(f"ERROR: Could not find installed application folder:\n{APP_DIR}")
        input("Press Enter to close...")
        return 1
    for rel, blob in FILES.items():
        target = APP_DIR / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            backup = target.with_suffix(target.suffix + ".before_replica_v1.bak")
            if not backup.exists():
                shutil.copy2(target, backup)
        target.write_bytes(gzip.decompress(base64.b64decode(blob)))
        print(f"Updated: {rel}")
    print()
    print("SUCCESS: OrderEntry Replica v1 has been installed.")
    print("The Pricing Engine v1.2 calculation layer was not replaced.")
    print("Restart RUN_CYLINDER_QUOTE.bat, then refresh the browser (Ctrl+F5 if needed).")
    input("Press Enter to close...")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())